class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10 ** 9 + 7
        from functools import lru_cache
        def f(s):
            n = len(s)
            @lru_cache(None)
            def dp(i, prev, tight, started):
                if i == n: return 1 if started else 0
                hi = int(s[i]) if tight else 9
                tot = 0
                for d in range(hi + 1):
                    nt = tight and d == hi
                    if not started:
                        if d == 0: tot += dp(i + 1, -1, nt, False)
                        else: tot += dp(i + 1, d, nt, True)
                    elif abs(d - prev) == 1:
                        tot += dp(i + 1, d, nt, True)
                return tot % MOD
            return dp(0, -1, True, False)
        def is_step(t):
            return all(abs(int(t[i]) - int(t[i + 1])) == 1 for i in range(len(t) - 1))
        return (f(high) - f(low) + (1 if is_step(low) else 0)) % MOD

