class Solution {
    static constexpr long long MOD = 1e9 + 7;
    string s;
    vector<array<array<array<long long,2>,2>,12>> memo;
    long long dfs(int i, int prev, int tight, int started) {
        if (i == (int)s.size()) return started;
        auto& r = memo[i][prev + 1][tight][started];
        if (r != -1) return r;
        int hi = tight ? s[i] - '0' : 9;
        long long tot = 0;
        for (int d = 0; d <= hi; d++) {
            int nt = tight && d == hi;
            if (!started) {
                if (d == 0) tot += dfs(i + 1, -1, nt, 0);
                else tot += dfs(i + 1, d, nt, 1);
            } else if (abs(d - prev) == 1) tot += dfs(i + 1, d, nt, 1);
        }
        return r = tot % MOD;
    }
    long long f(const string& str) {
        s = str;
        memo.assign(s.size() + 1, {});
        for (auto& a : memo) for (auto& b : a) for (auto& c : b) c.fill(-1);
        return dfs(0, -1, 1, 0);
    }
public:
    int countSteppingNumbers(string low, string high) {
        long long ans = (f(high) - f(low) % MOD + MOD) % MOD;
        bool step = true;
        for (int i = 0; i + 1 < (int)low.size(); i++)
            if (abs(low[i] - low[i + 1]) != 1) step = false;
        return (ans + (step ? 1 : 0)) % MOD;
    }
};

