class Solution {
    static final long MOD = 1_000_000_007L;
    String s;
    Long[][][][] memo;
    long dfs(int i, int prev, int tight, int started) {
        if (i == s.length()) return started;
        if (memo[i][prev + 1][tight][started] != null) return memo[i][prev + 1][tight][started];
        int hi = tight == 1 ? s.charAt(i) - '0' : 9;
        long tot = 0;
        for (int d = 0; d <= hi; d++) {
            int nt = (tight == 1 && d == hi) ? 1 : 0;
            if (started == 0) {
                if (d == 0) tot += dfs(i + 1, -1, nt, 0);
                else tot += dfs(i + 1, d, nt, 1);
            } else if (Math.abs(d - prev) == 1) tot += dfs(i + 1, d, nt, 1);
        }
        return memo[i][prev + 1][tight][started] = tot % MOD;
    }
    long f(String str) {
        s = str;
        memo = new Long[s.length() + 1][12][2][2];
        return dfs(0, -1, 1, 0);
    }
    public int countSteppingNumbers(String low, String high) {
        long ans = ((f(high) - f(low)) % MOD + MOD) % MOD;
        boolean step = true;
        for (int i = 0; i + 1 < low.length(); i++)
            if (Math.abs(low.charAt(i) - low.charAt(i + 1)) != 1) step = false;
        return (int) ((ans + (step ? 1 : 0)) % MOD);
    }
}

