var countSteppingNumbers = function(low, high) {
    const MOD = 1e9 + 7;
    const f = (s) => {
        const n = s.length, memo = {};
        const dfs = (i, prev, tight, started) => {
            if (i === n) return started ? 1 : 0;
            const key = i + '_' + prev + '_' + tight + '_' + started;
            if (key in memo) return memo[key];
            const hi = tight ? +s[i] : 9;
            let tot = 0;
            for (let d = 0; d <= hi; d++) {
                const nt = tight && d === hi ? 1 : 0;
                if (!started) {
                    if (d === 0) tot += dfs(i + 1, -1, nt, 0);
                    else tot += dfs(i + 1, d, nt, 1);
                } else if (Math.abs(d - prev) === 1) tot += dfs(i + 1, d, nt, 1);
            }
            return memo[key] = tot % MOD;
        };
        return dfs(0, -1, 1, 0);
    };
    const isStep = (t) => {
        for (let i = 0; i + 1 < t.length; i++) if (Math.abs(+t[i] - +t[i + 1]) !== 1) return false;
        return true;
    };
    return ((f(high) - f(low) + (isStep(low) ? 1 : 0)) % MOD + MOD) % MOD;
};
